// Hipótesis 2: Hay sesiones con una actividad anormalmente alta (posibles bots).
// Una sesión con muchísimos eventos en un corto período de tiempo puede ser un bot o un scraper. Buscaremos sesiones con más de 50 eventos, un umbral inicial que se puede ajustar.
MATCH (s:Session)-[:CONTIENE]->(:Event)
WITH s, count(*) AS numero_eventos
WHERE numero_eventos > 50
RETURN s.session_id, s.source, s.device, numero_eventos
ORDER BY numero_eventos DESC
LIMIT 10;

// Hipótesis 3: Cuantificar las conversiones realizadas por "invitados" vs. usuarios logueados.
// Esto no es necesariamente un error, pero es un patrón de negocio crucial. Permite entender qué porcentaje de las ventas proviene de usuarios no registrados.
MATCH (s:Session)-[:CONVERSION_REALIZADA]->(:Conversion)
OPTIONAL MATCH (u:User)-[:REALIZO]->(s)
WITH count(s) AS total_conversiones, count(CASE WHEN u IS NULL THEN 1 END) AS conversiones_invitado
RETURN
  total_conversiones,
  conversiones_invitado,
  round(100.0 * conversiones_invitado / total_conversiones, 2) AS porcentaje_invitado;

// Hipótesis 4: Existen usuarios que realizaron una conversión ANTES de su fecha de registro.
// Esto es lógicamente imposible y señalaría un problema grave en la ingesta de datos o en la atribución de fechas. Se busca en el historial del visitante asociado al usuario.
MATCH (u:User)<-[:IDENTIFIED_AS]-(:Visitor)-[:INICIO_SESION]->(s:Session)-[:CONVERSION_REALIZADA]->(:Conversion)
WHERE s.date < u.registration_date
RETURN u.user_id, u.registration_date, s.session_id, s.date AS conversion_date
LIMIT 25;

// Hipótesis 5: Hay sesiones "huérfanas" que no provienen de ningún visitante.
// Esto indicaría un problema grave en la ingesta de datos, ya que toda sesión debe ser iniciada por un visitante según el esquema.
MATCH (s:Session)
WHERE NOT EXISTS ((:Visitor)-[:INICIO_SESION]->(s))
RETURN s.session_id, s.date, s.source
LIMIT 100;

